// Health-risk example — key generation (patient side, CKKS)
//
// Generates the crypto context and every key. All of it lands in the
// patient's home; run_test.sh / the demo then copy only the context, public
// key and evaluation keys to the server. The secret key never leaves.
//
// Usage: ./health_risk_keygen [client_home [ring_dim]]
//   Defaults: client_home=health_risk_client, ring_dim=65536 (2^16).
//   A smaller ring is for quick local runs only (security check disabled).

#include "openfhe.h"

#include <filesystem>

#include "ciphertext-ser.h"
#include "cryptocontext-ser.h"
#include "key/key-ser.h"
#include "scheme/ckksrns/ckksrns-ser.h"

#include "common.hpp"

using namespace lbcrypto;
using namespace health_risk;

int main(int argc, char* argv[]) {
    std::string home = "health_risk_client";
    uint32_t ring_dim = kRingDim;
    if (argc > 1) home = argv[1];
    if (argc > 2) ring_dim = static_cast<uint32_t>(std::stoul(argv[2]));

    std::cout << "=== Health risk — Key Generation ===" << std::endl;
    std::filesystem::create_directories(home);

    CryptoContext<DCRTPoly> cc = make_context(ring_dim);

    std::cout << "Ring dimension: " << cc->GetRingDimension()
              << ", depth " << kDepth << ", scale " << kScalingModSize << " bits" << std::endl;

    auto keyPair = cc->KeyGen();
    cc->EvalMultKeyGen(keyPair.secretKey);
    cc->EvalRotateKeyGen(keyPair.secretKey, kRotations);

    if (!Serial::SerializeToFile(home + "/cc.bin", cc, SerType::BINARY))
        throw std::runtime_error("Failed to serialize crypto context");
    if (!Serial::SerializeToFile(home + "/pk.bin", keyPair.publicKey, SerType::BINARY))
        throw std::runtime_error("Failed to serialize public key");
    if (!Serial::SerializeToFile(home + "/sk.bin", keyPair.secretKey, SerType::BINARY))
        throw std::runtime_error("Failed to serialize secret key");

    std::ofstream mkStream(home + "/mk.bin", std::ios::out | std::ios::binary);
    if (!mkStream.is_open() || !cc->SerializeEvalMultKey(mkStream, SerType::BINARY))
        throw std::runtime_error("Failed to serialize eval mult key");
    mkStream.close();

    std::ofstream rkStream(home + "/rk.bin", std::ios::out | std::ios::binary);
    if (!rkStream.is_open() || !cc->SerializeEvalAutomorphismKey(rkStream, SerType::BINARY))
        throw std::runtime_error("Failed to serialize rotation keys");
    rkStream.close();

    std::cout << "Keys written to " << home << "/" << std::endl;
    return 0;
}
